package com.bank.refcode.service;

import java.util.logging.Logger;

// Longest palindromic subsequence via the two-ended range DP.
public class ReferenceCodeService {
    private static final Logger log = Logger.getLogger(ReferenceCodeService.class.getName());

    public int longestPalindromicCore(String code) {
        int n = code.length();
        int[][] dp = new int[n][n];                 // dp[i][j] over range i..j
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;                           // single char is a palindrome
            for (int j = i + 1; j < n; j++) {
                if (code.charAt(i) == code.charAt(j))
                    dp[i][j] = 2 + dp[i + 1][j - 1]; // ends match, wrap inner
                else
                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]); // drop one end
            }
        }
        final int r = n == 0 ? 0 : dp[0][n - 1];
        log.info(() -> "Longest palindromic core of " + code + " = " + r);
        return r;
    }
}
